typedef unsigned int u_int;
#define NULL 0

struct nglFileBuf
{
    unsigned char* Buf;
    u_int Size;
    u_int UserData;
};

class stringx
{
    char* chars;
    void* my_buf;

public:
    stringx(const char* str, int len = -1);
    ~stringx();
    stringx& operator=(const stringx& cp);
};

enum
{
    GT_LAST = 650,
    BUTTON_LAST = 21,
    LANGUAGE_LAST = 4,
    PLATFORM_PS2 = 0,
    PLATFORM_LAST = 3
};

extern stringx ksGlobalTextArray[GT_LAST];
extern stringx ksGlobalButtonArray[BUTTON_LAST];
extern int ksGlobalTextLanguage;

bool KSReadFile(const char* FileName, nglFileBuf* File, u_int Align);
void KSReleaseFile(nglFileBuf* File);

#define assert(condition) ((void)0)
#define TARGET_PS2

void GLOBALTEXT_Load()
{
    nglFileBuf file;
    file.Buf = NULL;
    file.Size = 0;
    KSReadFile("globaltext.dat", &file, 1);
    char* buffer = (char*) file.Buf;
    if(!buffer)
    {
         KSReleaseFile(&file);
         assert(0);
    }

    char word[512];
    int row_num = 0;
    int lang_num = 0;
    int plat_num = 0;
    int word_ct = 0;
    char c;
    bool found_start = false;
    bool in_word = false;

    for(int i=0; i<(signed)file.Size; i++)
    {
         c = buffer[i];
         if((c == ' ' && !in_word) || c == '\t' || c == '\r' || (c == '\n' && !found_start)) continue;
         found_start = true;
         if(c == '\n')
         {
              word[word_ct] = '\0';
              if(row_num < GT_LAST)
              {
                   if(lang_num == ksGlobalTextLanguage)
                        ksGlobalTextArray[row_num] = stringx(word);
                   lang_num++;
                   word_ct = 0;
                   in_word = false;
                   if(lang_num >= LANGUAGE_LAST)
                   {
                        lang_num = 0;
                        row_num++;
                   }
              }
              else
              {
                   assert(row_num < GT_LAST + BUTTON_LAST);
#ifdef TARGET_PS2
                   if(plat_num == PLATFORM_PS2)
                        ksGlobalButtonArray[row_num-GT_LAST] = stringx(word);
#endif
#ifdef TARGET_XBOX
                   if(plat_num == PLATFORM_XBOX)
                        ksGlobalButtonArray[row_num-GT_LAST] = stringx(word);
#endif
#ifdef TARGET_GC
                   if(plat_num == PLATFORM_GC)
                        ksGlobalButtonArray[row_num-GT_LAST] = stringx(word);
#endif
                   plat_num++;
                   word_ct = 0;
                   in_word = false;
                   if(plat_num >= PLATFORM_LAST)
                   {
                        plat_num = 0;
                        row_num++;
                   }
              }
         }
         else
         {
              in_word = true;
              assert(word_ct < 512);
              word[word_ct] = c;
              word_ct++;
         }
    }

    KSReleaseFile(&file);
}
